import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen2Test {













    @Test
    public void testEquals_NaN_BothNaN() {
        // In Complex implementation, isNaN() check is triggered if rhs.isNaN() is true
        // We use Double.NaN to create NaN complex numbers
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(Double.NaN, Double.NaN);
        assertTrue("Should return true if both are NaN", c1.equals(c2));
    }








}

