package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen2Test {



















    @Test
    public void testEquals_EdgeCases_ZeroAndNegativeZero() {
        // Double.doubleToRawLongBits distinguishes between 0.0 and -0.0
        Complex c1 = new Complex(0.0, 0.0);
        Complex c2 = new Complex(-0.0, -0.0);
        assertFalse("Should return false for 0.0 vs -0.0 due to rawLongBits comparison", c1.equals(c2));

        Complex c3 = new Complex(0.0, -0.0);
        assertFalse("Should return false for 0.0 vs -0.0 in imaginary part", c1.equals(c3));
    }


}

package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen2Test {





















    @Test
    public void testEquals_Infinity() {
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
        Complex c2 = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
        assertTrue("Should handle infinity correctly", c1.equals(c2));

        Complex c3 = new Complex(Double.NEGATIVE_INFINITY, Double.POSITIVE_INFINITY);
        assertFalse("Should return false for different infinities", c1.equals(c3));
    }
}
